def glob_match(pattern: str, s: str) -> bool:
    def parse_set(p, i):
        # p[i] == '[', parse until ']'; returns (negate, chars_set, ranges, next_i)
        i += 1
        negate = False
        if i < len(p) and p[i] == '!':
            negate = True
            i += 1
        chars = set()
        ranges = []
        items = []
        first = True
        while i < len(p):
            if p[i] == ']' and not first:
                return negate, items, i + 1
            first = False
            if p[i] == '-' and items and items[-1] != ('range',) and i + 1 < len(p) and p[i+1] != ']':
                lo = items.pop()
                hi = p[i+1]
                items.append(('range', lo, hi))
                i += 2
            else:
                items.append(p[i])
                i += 1
        return None, None, None  # unterminated -> literal

    def match(p, s, pi, si, memo={}):
        while pi < len(p):
            c = p[pi]
            if c == '?':
                if si >= len(s):
                    return False
                pi += 1; si += 1
            elif c == '*':
                # collapse consecutive stars
                while pi < len(p) and p[pi] == '*':
                    pi += 1
                if pi == len(p):
                    return True
                for k in range(si, len(s) + 1):
                    if match(p, s, pi, k):
                        return True
                return False
            elif c == '[':
                parsed = parse_set(p, pi)
                if parsed[0] is None:
                    if si >= len(s) or s[si] != '[':
                        return False
                    pi += 1; si += 1
                else:
                    negate, items, nxt = parsed
                    if si >= len(s):
                        return False
                    ch = s[si]
                    ok = False
                    for it in items:
                        if isinstance(it, tuple) and it[0] == 'range':
                            if it[1] <= ch <= it[2]:
                                ok = True
                        elif ch == it:
                            ok = True
                    if negate:
                        ok = not ok
                    if not ok:
                        return False
                    pi = nxt; si += 1
            else:
                if si >= len(s) or s[si] != c:
                    return False
                pi += 1; si += 1
        return si == len(s)

    return match(pattern, s, 0, 0)
