```python
def wrap_text(text: str, width: int) -> list[str]:
    words = text.split()
    lines: list[str] = []
    cur: list[str] = []
    cur_len = 0

    def flush():
        nonlocal cur, cur_len
        if cur:
            lines.append(' '.join(cur))
            cur = []
            cur_len = 0

    for w in words:
        if len(w) > width:
            flush()
            pieces = [w[i:i + width] for i in range(0, len(w), width)]
            for p in pieces[:-1]:
                lines.append(p)
            cur = [pieces[-1]]
            cur_len = len(pieces[-1])
        else:
            add = len(w) if not cur else cur_len + 1 + len(w)
            if cur_len + add <= width if not cur else add <= width:
                cur.append(w)
                cur_len += add
            else:
                flush()
                cur = [w]
                cur_len = len(w)
    flush()
    return lines
