def apply_transfers(balances: dict[str, int], transfers: list[dict]) -> dict:
    out = dict(balances)
    rejected = []
    for t in transfers:
        src, dst = t.get("from"), t.get("to")
        amount = t.get("amount")
        if src not in out or dst not in out or src == dst:
            rejected.append(t["id"])
            continue
        if isinstance(amount, bool) or not isinstance(amount, int) or amount <= 0:
            rejected.append(t["id"])
            continue
        if out[src] - amount < 0:
            rejected.append(t["id"])
            continue
        out[src] -= amount
        out[dst] += amount
    return {"balances": out, "rejected": rejected}
