```python
def topo_sort(deps):
    nodes = set(deps)
    for ds in deps.values():
        nodes.update(ds)
    remaining = {n: set(deps.get(n, [])) & nodes for n in nodes}
    result = []
    while remaining:
        ready = sorted(n for n, ds in remaining.items() if not ds)
        if not ready:
            raise ValueError("cycle detected")
        n = ready[0]
        result.append(n)
        del remaining[n]
        for ds in remaining.values():
            ds.discard(n)
    return result
