from collections import defaultdict

def parse_query(qs: str) -> dict[str, list[str]]:
    result = defaultdict(list)
    for pair in qs.split('&'):
        if not pair:
            continue
        key, sep, value = pair.partition('=')
        result[_decode(key)].append(_decode(value))
    return dict(result)

def _decode(s: str) -> str:
    out = bytearray()
    i = 0
    while i < len(s):
        c = s[i]
        if c == '+':
            out.append(32)
            i += 1
        elif c == '%' and i + 2 < len(s) + 1 and i + 2 <= len(s) - 1 + 1 and i + 2 < len(s) + 1:
            pass
        if c == '%' and i + 2 < len(s) + 1 and i + 3 <= len(s):
            hexpart = s[i+1:i+3]
            if len(hexpart) == 2 and all(ch in '0123456789abcdefABCDEF' for ch in hexpart):
                out.append(int(hexpart, 16))
                i += 3
            else:
                raise ValueError('bad percent escape')
        elif c != '%' and c != '+':
            out.extend(c.encode('utf-8'))
            i += 1
        elif c == '%' and i + 3 > len(s):
            raise ValueError('bad percent escape')
    try:
        return out.decode('utf-8')
    except UnicodeDecodeError:
        raise ValueError('bad UTF-8')
```

