def apply_transfers(balances: dict[str, int], transfers: list[dict]) -> dict:
    final_balances = dict(balances)
    rejected = []

    for transfer in transfers:
        transfer_id = transfer["id"]
        sender = transfer["from"]
        receiver = transfer["to"]
        amount = transfer["amount"]

        if not isinstance(amount, int) or isinstance(amount, bool) or amount <= 0:
            rejected.append(transfer_id)
            continue

        if sender not in final_balances or receiver not in final_balances:
            rejected.append(transfer_id)
            continue

        if sender == receiver:
            rejected.append(transfer_id)
            continue

        if final_balances[sender] - amount < 0:
            rejected.append(transfer_id)
            continue

        final_balances[sender] -= amount
        final_balances[receiver] += amount

    return {"balances": final_balances, "rejected": rejected}
```

