        amount = transfer["amount"]

        if (
            from_account not in new_balances
            or to_account not in new_balances
            or from_account == to_account
            or not isinstance(amount, int)
            or isinstance(amount, bool)
            or amount <= 0
            or new_balances[from_account] < amount
        ):
            rejected.append(transfer_id)
            continue

        new_balances[from_account] -= amount
        new_balances[to_account] += amount

    return {"balances": new_balances, "rejected": rejected}
