def apply_transfers(balances: dict[str, int], transfers: list[dict]) -> dict:
    # Work on a copy so the input dict is not mutated
    final_balances = balances.copy()
    rejected_ids = []

    for tr in transfers:
        tr_id = tr.get("id")
        frm = tr.get("from")
        to = tr.get("to")
        amt = tr.get("amount")

        # Validation checks
        invalid = False
        if not isinstance(amt, int) or isinstance(amt, bool) or amt <= 0:
            invalid = True
        elif frm not in final_balances or to not in final_balances:
            invalid = True
        elif frm == to:
            invalid = True
        elif final_balances[frm] - amt < 0:
            invalid = True

        if invalid:
            rejected_ids.append(tr_id)
            continue

        # Apply transfer
        final_balances[frm] -= amt
        final_balances[to] += amt

    return {"balances": final_balances, "rejected": rejected_ids}
