import urllib.parse

def _decode_component(comp: str) -> str:
    """Decode a URL component, handling '+' as space and %XX as UTF‑8."""
    # Replace '+' with space first (urllib.parse.unquote_plus does both,
    # but we need to raise on malformed % sequences, so implement manually)
    result = []
    i = 0
    length = len(comp)
    while i < length:
        ch = comp[i]
        if ch == '+':
            result.append(' ')
            i += 1
        elif ch == '%':
            if i + 2 >= length:
                raise ValueError("Incomplete percent-escape")
            hex_part = comp[i+1:i+3]
            try:
                byte = int(hex_part, 16)
            except ValueError:
                raise ValueError("Invalid percent-escape")
            result.append(chr(byte))
            i += 3
        else:
            result.append(ch)
            i += 1
    # The string may contain bytes >127 that need UTF‑8 decoding.
    # Join as bytes and decode.
    byte_str = ''.join(result).encode('latin-1')
    return byte_str.decode('utf-8')

def parse_query(qs: str) -> dict[str, list[str]]:
    if not qs:
        return {}
    result: dict[str, list[str]] = {}
    pairs = qs.split('&')
    for pair in pairs:
        if pair == '':
            continue  # skip empty pairs
        if '=' in pair:
            key_raw, value_raw = pair.split('=', 1)
        else:
            key_raw, value_raw = pair, ''
        key = _decode_component(key_raw)
        value = _decode_component(value_raw)
        result.setdefault(key, []).append(value)
    return result
