import urllib.parse

def _decode_component(comp: str) -> str:
    # Replace '+' with space before percent-decoding
    comp = comp.replace('+', ' ')
    # Percent-decode with strict error handling
    try:
        # urllib.parse.unquote_to_bytes returns bytes; then decode as UTF-8
        raw = urllib.parse.unquote_to_bytes(comp)
    except Exception as e:
        # urllib may raise generic exceptions for bad percent-escapes
        raise ValueError('Invalid percent-encoding') from e
    try:
        return raw.decode('utf-8')
    except UnicodeDecodeError as e:
        raise ValueError('Invalid UTF-8 in percent-encoding') from e

def parse_query(qs: str) -> dict[str, list[str]]:
    result: dict[str, list[str]] = {}
    if not qs:
        return result
    for pair in qs.split('&'):
        if pair == '':
            continue  # skip empty pairs
        if '=' in pair:
            key_raw, value_raw = pair.split('=', 1)
        else:
            key_raw, value_raw = pair, ''
        key = _decode_component(key_raw)
        value = _decode_component(value_raw)
        result.setdefault(key, []).append(value)
    return result
