    # Use urllib.parse.unquote_to_bytes to get raw bytes then decode UTF-8
    try:
        b = urllib.parse.unquote_to_bytes(comp)
    except Exception as e:
        raise ValueError('Invalid percent-encoding') from e
    try:
        return b.decode('utf-8')
    except UnicodeDecodeError as e:
        raise ValueError('Invalid UTF-8 sequence') from e

def parse_query(qs: str) -> dict[str, list[str]]:
    result: dict[str, list[str]] = {}
    if not qs:
        return result
    pairs = qs.split('&')
    for pair in pairs:
        if not pair:
            continue
        if '=' in pair:
            key, value = pair.split('=', 1)
        else:
            key, value = pair, ''
        try:
            decoded_key = _decode_component(key)
            decoded_value = _decode_component(value)
        except ValueError as e:
            raise
        result.setdefault(decoded_key, []).append(decoded_value)
    return result
```

