import urllib.parse

def _decode_component(comp: str) -> str:
    # Replace '+' with space
    comp = comp.replace('+', ' ')
    # Percent-decode with strict handling
    i = 0
    out = bytearray()
    while i < len(comp):
        if comp[i] == '%':
            if i + 2 >= len(comp):
                raise ValueError("Incomplete percent-escape")
            hex_part = comp[i+1:i+3]
            try:
                byte = int(hex_part, 16)
            except ValueError:
                raise ValueError("Invalid percent-escape")
            out.append(byte)
            i += 3
        else:
            out.extend(comp[i].encode('utf-8'))
            i += 1
    return out.decode('utf-8')

def parse_query(qs: str) -> dict[str, list[str]]:
    result: dict[str, list[str]] = {}
    if not qs:
        return result
    pairs = qs.split('&')
    for pair in pairs:
        if pair == '':
            continue  # skip empty pairs
        if '=' in pair:
            key_raw, value_raw = pair.split('=', 1)
        else:
            key_raw, value_raw = pair, ''
        key = _decode_component(key_raw)
        value = _decode_component(value_raw)
        result.setdefault(key, []).append(value)
    return result
