from copy import deepcopy
from typing import Dict, List

def apply_transfers(balances: dict[str, int], transfers: list[dict]) -> dict:
    # work on a copy to avoid mutating the input
    cur_bal: Dict[str, int] = deepcopy(balances)
    rejected: List[str] = []

    for tr in transfers:
        tr_id = tr.get("id")
        frm = tr.get("from")
        to = tr.get("to")
        amount = tr.get("amount")

        # validation checks
        invalid = False

        # accounts must exist and be distinct
        if frm not in cur_bal or to not in cur_bal or frm == to:
            invalid = True
        # amount must be int, not bool, and > 0
        elif not isinstance(amount, int) or isinstance(amount, bool) or amount <= 0:
            invalid = True
        # sender must have enough funds
        elif cur_bal[frm] - amount < 0:
            invalid = True

        if invalid:
            rejected.append(tr_id)
            continue

        # apply transfer
        cur_bal[frm] -= amount
        cur_bal[to] += amount

    return {"balances": cur_bal, "rejected": rejected}
