def apply_transfers(balances: dict[str, int], transfers: list[dict]) -> dict:
    # Work on a copy to avoid mutating the input balances
    final_balances = balances.copy()
    rejected_ids = []

    for tr in transfers:
        tr_id = tr.get("id")
        src = tr.get("from")
        dst = tr.get("to")
        amount = tr.get("amount")

        # Validation checks
        invalid = False

        # existence of accounts
        if src not in final_balances or dst not in final_balances:
            invalid = True
        # same account
        elif src == dst:
            invalid = True
        # amount must be int, not bool, and positive
        elif not isinstance(amount, int) or isinstance(amount, bool) or amount <= 0:
            invalid = True
        # sufficient funds
        elif final_balances[src] < amount:
            invalid = True

        if invalid:
            rejected_ids.append(tr_id)
            continue

        # Apply transfer
        final_balances[src] -= amount
        final_balances[dst] += amount

    return {"balances": final_balances, "rejected": rejected_ids}
